INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('287', '95', 'user', 'What is Python programming?', 'system', 'USER_INPUT', '1.00', '2026-08-17 18:04:32');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('288', '95', 'bot', '<p class=\'mb-2\'>### Python Programming Language Overview</p><p class=\'mb-2\'>Python is a high-level, interpreted, general-purpose programming language renowned for its readable syntax, extensive standard libraries, and dynamic typing.</p>Common Applications:\n<ul class=\'ps-3 mb-2 small\'><li class=\'mb-1\'>Artificial Intelligence & Machine Learning (TensorFlow, PyTorch, Scikit-Learn)</li><li class=\'mb-1\'>Data Science & Analytics (Pandas, NumPy, Matplotlib)</li><li class=\'mb-1\'>Web Backend Development (Django, Flask, FastAPI)</li></ul><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/courses.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'CODING', '0.88', '2026-08-17 18:04:32');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('289', '96', 'user', 'Explain Binary Search algorithm', 'system', 'USER_INPUT', '1.00', '2026-08-17 18:04:32');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('290', '96', 'bot', '<p class=\'mb-2\'>### Binary Search Algorithm</p><p class=\'mb-2\'>Binary Search is an efficient searching algorithm that operates on sorted arrays with a time complexity of O(log n).</p><p class=\'mb-2\'>Here is a C implementation of Binary Search:</p><p class=\'mb-2\'><div class=\'code-block-wrapper my-2\'><div class=\'code-block-header d-flex justify-content-between px-3 py-1 bg-dark text-white-50 rounded-top small font-monospace\'><span>c</span><button class=\'btn btn-link btn-sm text-white-50 p-0 copy-code-btn\' onclick=\'navigator.clipboard.writeText(this.parentNode.nextElementSibling.innerText)\'><i class=\'fa-regular fa-copy me-1\'></i>Copy</button></div><pre class=\'bg-dark text-light p-3 rounded-bottom mb-0 font-monospace\' style=\'max-height:300px; overflow-y:auto;\'><code>#include &lt;stdio.h&gt;</p><p class=\'mb-2\'>int binarySearch(int arr[], int size, int target) {<br />\n    int low = 0, high = size - 1;<br />\n    while (low &lt;= high) {<br />\n        int mid = low + (high - low) / 2;<br />\n        if (arr[mid] == target) return mid;<br />\n        if (arr[mid] &lt; target) low = mid + 1;<br />\n        else high = mid - 1;<br />\n    }<br />\n    return -1;<br />\n}</p><p class=\'mb-2\'>int main() {<br />\n    int arr[] = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};<br />\n    int size = sizeof(arr) / sizeof(arr[0]);<br />\n    int target = 23;<br />\n    int result = binarySearch(arr, size, target);<br />\n    if (result != -1)<br />\n        printf(&quot;Element found at index %d&quot;, result);<br />\n    else<br />\n        printf(&quot;Element not found&quot;);<br />\n    return 0;<br />\n}</code></pre></div></p>Key Advantages:\n<ul class=\'ps-3 mb-2 small\'><li class=\'mb-1\'>Time Complexity: Best O(1), Average O(log n), Worst O(log n).</li><li class=\'mb-1\'>Space Complexity: O(1) iterative.</li></ul><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'CODING', '0.90', '2026-08-17 18:04:32');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('291', '97', 'user', 'What is Blockchain technology?', 'system', 'USER_INPUT', '1.00', '2026-08-17 18:04:32');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('292', '97', 'bot', '<p class=\'mb-2\'>### Blockchain Technology Overview</p><p class=\'mb-2\'>Blockchain is a decentralized, distributed, digital ledger technology that records transactions across a network of computers in an immutable and tamper-evident manner.</p>Key Pillars:\n<ul class=\'ps-3 mb-2 small\'><li class=\'mb-1\'>Decentralization: No single central authority controls the ledger.</li><li class=\'mb-1\'>Immutability: Cryptographic hashing prevents data modification after block confirmation.</li><li class=\'mb-1\'>Consensus Mechanisms: Proof of Work (PoW) or Proof of Stake (PoS) validate transactions.</li></ul><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'CODING', '0.88', '2026-08-17 18:04:32');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('293', '98', 'user', 'What is Docker?', 'system', 'USER_INPUT', '1.00', '2026-08-17 18:04:32');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('294', '98', 'bot', '<p class=\'mb-2\'>### Docker</p><p class=\'mb-2\'>Docker is a platform for developing, shipping, and running applications in containers. Containers package code and dependencies. Key concepts include Images, Dockerfile, and Docker Compose.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'GENERAL_AI', '0.90', '2026-08-17 18:04:32');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('295', '99', 'user', 'What is the admission eligibility for B.Tech at SOET?', 'system', 'USER_INPUT', '1.00', '2026-08-17 18:09:53');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('296', '99', 'bot', '<p class=\'mb-2\'>Candidates must have passed 10+2 with Physics and Mathematics as compulsory subjects with 45% aggregate marks (40% for SC/ST/OBC). MHT-CET or JEE Main score card is required.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/contact.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'ADMISSION', '0.94', '2026-08-17 18:09:53');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('340', '103', 'user', 'location', 'system', 'USER_INPUT', '1.00', '2026-08-18 12:46:12');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('341', '103', 'bot', '<p class=\'mb-2\'>School of Engineering & Technology (SOET) is a premier engineering constituent college of MGM University located in Chhatrapati Sambhajinagar (Aurangabad), Maharashtra, India. SOET offers cutting-edge B.Tech, M.Tech, and Ph.D. programs with state-of-the-art laboratories, industry tie-ups, and top-tier placement opportunities.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/about.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'CONTACT', '0.94', '2026-08-18 12:46:12');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('342', '104', 'user', 'What are the courses offered in SOET?', 'system', 'USER_INPUT', '1.00', '2026-08-18 17:49:41');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('343', '104', 'bot', '<p class=\'mb-2\'>SOET offers 4-Year B.Tech Degree Programs in: 1. Computer Science & Engineering (CSE) 2. CSE with specialization in Cyber Security 3. CSE with specialization in Data Science & Artificial Intelligence 4. Electronics & Telecommunication Engineering (ECE) 5. Mechanical Engineering 6. Civil Engineering 7. Robotics & Automation Engineering. Integrated 6-Year B.Tech programs after 10th (SSC) are also offered.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/courses.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'PROGRAM', '0.94', '2026-08-18 17:49:41');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('344', '105', 'user', 'Tell me about B.Tech Computer Science and Engineering fees', 'system', 'USER_INPUT', '1.00', '2026-08-18 17:49:41');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('345', '105', 'bot', '<p class=\'mb-2\'>SOET offers B.Tech in Computer Science & Engineering (BTECH-CSE) under Computer Science & Engineering. Duration: 4 Years (8 Semesters). Intake Capacity: 120 seats. Description: A comprehensive 4-year degree focusing on Data Structures, Software Engineering, Full-Stack Web Development, Cloud Computing, and Artificial Intelligence..</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/courses.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'DEPARTMENT', '0.94', '2026-08-18 17:49:41');
