INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('357', '111', 'bot', '<p class=\'mb-2\'>SOET offers B.Tech in CSE (Cyber Security & Digital Forensics) (BTECH-CS) under Computer Science & Engineering. Duration: 4 Years (8 Semesters). Intake Capacity: 60 seats. Description: Specialized degree focusing on Network Cryptography, Ethical Hacking, Cyber Forensics, Cloud Security, and Risk Assessment..</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/courses.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'PROGRAM', '0.94', '2026-08-18 17:49:41');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('358', '112', 'user', 'What is Cloud Computing?', 'system', 'USER_INPUT', '1.00', '2026-08-18 17:49:41');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('359', '112', 'bot', '<p class=\'mb-2\'>### Cloud Computing</p><p class=\'mb-2\'>Cloud computing provides on-demand delivery of IT resources. Service models include IaaS (Infrastructure as a Service), PaaS (Platform as a Service), and SaaS (Software as a Service). Major providers are AWS, Microsoft Azure, and Google Cloud Platform (GCP).</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'GENERAL_AI', '0.90', '2026-08-18 17:49:41');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('360', '113', 'user', 'Explain the difference between Python and C++', 'system', 'USER_INPUT', '1.00', '2026-08-18 17:49:41');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('361', '113', 'bot', '<p class=\'mb-2\'>### Python Programming Language Overview</p><p class=\'mb-2\'>Python is a high-level, interpreted, general-purpose programming language renowned for its readable syntax, extensive standard libraries, and dynamic typing.</p>Common Applications:\n<ul class=\'ps-3 mb-2 small\'><li class=\'mb-1\'>Artificial Intelligence & Machine Learning (TensorFlow, PyTorch, Scikit-Learn)</li><li class=\'mb-1\'>Data Science & Analytics (Pandas, NumPy, Matplotlib)</li><li class=\'mb-1\'>Web Backend Development (Django, Flask, FastAPI)</li></ul><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'CODING', '0.90', '2026-08-18 17:49:41');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('362', '114', 'user', 'What is Artificial Intelligence?', 'system', 'USER_INPUT', '1.00', '2026-08-18 17:49:41');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('363', '114', 'bot', '<p class=\'mb-2\'>### Artificial Intelligence (AI)</p><p class=\'mb-2\'>Artificial Intelligence refers to the simulation of human intelligence by software-coded heuristics. Types include Narrow AI (designed for specific tasks) and General AI (human-level intelligence). Applications span natural language processing, computer vision, expert systems, and robotics.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'GENERAL_AI', '0.90', '2026-08-18 17:49:41');
