INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('374', '120', 'user', 'Tell me about B.Tech Computer Science and Engineering fees', 'system', 'USER_INPUT', '1.00', '2026-08-18 17:52:52');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('375', '120', 'bot', '<p class=\'mb-2\'>SOET offers B.Tech in Computer Science & Engineering (BTECH-CSE) under Computer Science & Engineering. Duration: 4 Years (8 Semesters). Intake Capacity: 120 seats. Description: A comprehensive 4-year degree focusing on Data Structures, Software Engineering, Full-Stack Web Development, Cloud Computing, and Artificial Intelligence..</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/courses.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'DEPARTMENT', '0.94', '2026-08-18 17:52:52');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('376', '121', 'user', 'Who is the HOD of Computer Science?', 'system', 'USER_INPUT', '1.00', '2026-08-18 17:52:52');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('377', '121', 'bot', '<p class=\'mb-2\'>You can contact the CSE HOD via email at cse.hod@soet.edu or visit the CSE Department office in Academic Block 2, 1st Floor.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/contact.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'DEPARTMENT', '0.94', '2026-08-18 17:52:52');
