INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('415', '134', 'bot', '<p class=\'mb-2\'>**Branch** — I don\'t have a detailed built-in explanation for this topic right now, but I\'d be happy to help! Try asking me a more specific question, or explore the SOET website for academic resources.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'GENERAL_AI', '0.90', '2026-08-18 17:56:58');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('416', '134', 'user', 'Courses', 'system', 'USER_INPUT', '1.00', '2026-08-18 17:57:13');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('417', '134', 'bot', '<p class=\'mb-2\'>SOET offers 4-Year B.Tech Degree Programs in: 1. Computer Science & Engineering (CSE) 2. CSE with specialization in Cyber Security 3. CSE with specialization in Data Science & Artificial Intelligence 4. Electronics & Telecommunication Engineering (ECE) 5. Mechanical Engineering 6. Civil Engineering 7. Robotics & Automation Engineering. Integrated 6-Year B.Tech programs after 10th (SSC) are also offered.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/courses.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'PROGRAM', '0.94', '2026-08-18 17:57:13');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('418', '134', 'user', 'admission', 'system', 'USER_INPUT', '1.00', '2026-08-18 17:57:48');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('419', '134', 'bot', '<p class=\'mb-2\'>Candidates must have passed 10+2 with Physics and Mathematics as compulsory subjects with 45% aggregate marks (40% for SC/ST/OBC). MHT-CET or JEE Main score card is required.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/contact.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'ADMISSION', '0.94', '2026-08-18 17:57:48');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('420', '134', 'user', 'java', 'system', 'USER_INPUT', '1.00', '2026-08-18 17:57:59');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('421', '134', 'bot', '<p class=\'mb-2\'>### Java Object-Oriented Programming</p><p class=\'mb-2\'>Java is a class-based, object-oriented programming language designed for platform independence via the Java Virtual Machine (JVM) (\'Write Once, Run Anywhere\').</p>OOP Principles in Java:\n<ul class=\'ps-3 mb-2 small\'><li class=\'mb-1\'>Encapsulation: Bundling data and methods into classes.</li><li class=\'mb-1\'>Inheritance: Reusing code through class hierarchies.</li><li class=\'mb-1\'>Polymorphism: Method overloading and overriding.</li><li class=\'mb-1\'>Abstraction: Hiding implementation details using interfaces and abstract classes.</li></ul><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'CODING', '0.90', '2026-08-18 17:57:59');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('422', '134', 'user', 'python', 'system', 'USER_INPUT', '1.00', '2026-08-18 17:58:03');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('423', '134', 'bot', '<p class=\'mb-2\'>### Python Programming Language Overview</p><p class=\'mb-2\'>Python is a high-level, interpreted, general-purpose programming language renowned for its readable syntax, extensive standard libraries, and dynamic typing.</p>Common Applications:\n<ul class=\'ps-3 mb-2 small\'><li class=\'mb-1\'>Artificial Intelligence & Machine Learning (TensorFlow, PyTorch, Scikit-Learn)</li><li class=\'mb-1\'>Data Science & Analytics (Pandas, NumPy, Matplotlib)</li><li class=\'mb-1\'>Web Backend Development (Django, Flask, FastAPI)</li></ul><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'CODING', '0.90', '2026-08-18 17:58:03');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('424', '134', 'user', 'blickchain', 'system', 'USER_INPUT', '1.00', '2026-08-18 17:58:07');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('425', '134', 'bot', '<p class=\'mb-2\'>### Artificial Intelligence (AI)</p><p class=\'mb-2\'>Artificial Intelligence refers to the simulation of human intelligence by software-coded heuristics. Types include Narrow AI (designed for specific tasks) and General AI (human-level intelligence). Applications span natural language processing, computer vision, expert systems, and robotics.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'GENERAL_AI', '0.90', '2026-08-18 17:58:07');
