INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('427', '134', 'bot', '<p class=\'mb-2\'>The CSE department at SOET offers a 4-year B.Tech in Computer Science & Engineering with an intake capacity of 120 seats. The curriculum covers Artificial Intelligence, Machine Learning, Cloud Computing, Cybersecurity, Full-Stack Web Development, and Data Structures. Total annual fee is RS 140000 per academic year.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/courses.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'PROGRAM', '0.94', '2026-08-18 17:58:11');
