INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('439', '137', 'bot', '<p class=\'mb-2\'>You can contact the CSE HOD via email at cse.hod@soet.edu or visit the CSE Department office in Academic Block 2, 1st Floor.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/contact.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'DEPARTMENT', '0.94', '2026-08-18 23:26:40');
