INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('463', '149', 'bot', '<p class=\'mb-2\'>SOET offers 4-Year B.Tech Degree Programs in: 1. Computer Science & Engineering (CSE) 2. CSE with specialization in Cyber Security 3. CSE with specialization in Data Science & Artificial Intelligence 4. Electronics & Telecommunication Engineering (ECE) 5. Mechanical Engineering 6. Civil Engineering 7. Robotics & Automation Engineering. Integrated 6-Year B.Tech programs after 10th (SSC) are also offered.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/courses.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'CAREER', '0.94', '2026-08-18 23:26:41');
