INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('467', '151', 'bot', '<p class=\'mb-2\'>School of Engineering & Technology (SOET) is a premier engineering constituent college of MGM University located in Chhatrapati Sambhajinagar (Aurangabad), Maharashtra, India. SOET offers cutting-edge B.Tech, M.Tech, and Ph.D. programs with state-of-the-art laboratories, industry tie-ups, and top-tier placement opportunities.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/about.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'GENERAL_AI', '0.94', '2026-08-19 13:01:16');
