INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('473', '151', 'bot', '<p class=\'mb-2\'>SOET is led by Dr. Rajesh Kumar Sen, Dean & Director of SOET. Dr. Sen holds a Ph.D. in Computer Science & Engineering with over 22 years of academic and research leadership. Welcome message: SOET is not just a college; it is an ecosystem of tech innovation. We welcome you to experience an education that shapes you into a global leader.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/about.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'FACULTY', '0.94', '2026-08-19 13:06:39');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('474', '151', 'user', 'Write a C program for binary search and explain it', 'system', 'USER_INPUT', '1.00', '2026-08-19 13:06:59');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('475', '151', 'bot', '<p class=\'mb-2\'>### Binary Search Algorithm</p><p class=\'mb-2\'>Binary Search is an efficient searching algorithm that operates on sorted arrays with a time complexity of O(log n).</p><p class=\'mb-2\'>Here is a C implementation of Binary Search:</p><p class=\'mb-2\'><div class=\'code-block-wrapper my-2\'><div class=\'code-block-header d-flex justify-content-between px-3 py-1 bg-dark text-white-50 rounded-top small font-monospace\'><span>c</span><button class=\'btn btn-link btn-sm text-white-50 p-0 copy-code-btn\' onclick=\'navigator.clipboard.writeText(this.parentNode.nextElementSibling.innerText)\'><i class=\'fa-regular fa-copy me-1\'></i>Copy</button></div><pre class=\'bg-dark text-light p-3 rounded-bottom mb-0 font-monospace\' style=\'max-height:300px; overflow-y:auto;\'><code>#include &lt;stdio.h&gt;</p><p class=\'mb-2\'>int binarySearch(int arr[], int size, int target) {<br />\n    int low = 0, high = size - 1;<br />\n    while (low &lt;= high) {<br />\n        int mid = low + (high - low) / 2;<br />\n        if (arr[mid] == target) return mid;<br />\n        if (arr[mid] &lt; target) low = mid + 1;<br />\n        else high = mid - 1;<br />\n    }<br />\n    return -1;<br />\n}</p><p class=\'mb-2\'>int main() {<br />\n    int arr[] = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};<br />\n    int size = sizeof(arr) / sizeof(arr[0]);<br />\n    int target = 23;<br />\n    int result = binarySearch(arr, size, target);<br />\n    if (result != -1)<br />\n        printf(&quot;Element found at index %d&quot;, result);<br />\n    else<br />\n        printf(&quot;Element not found&quot;);<br />\n    return 0;<br />\n}</code></pre></div></p>Key Advantages:\n<ul class=\'ps-3 mb-2 small\'><li class=\'mb-1\'>Time Complexity: Best O(1), Average O(log n), Worst O(log n).</li><li class=\'mb-1\'>Space Complexity: O(1) iterative.</li></ul><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/about.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'CODING', '0.88', '2026-08-19 13:06:59');
