INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('481', '153', 'bot', '<p class=\'mb-2\'>### Java Object-Oriented Programming</p><p class=\'mb-2\'>Java is a class-based, object-oriented programming language designed for platform independence via the Java Virtual Machine (JVM) (\'Write Once, Run Anywhere\').</p>OOP Principles in Java:\n<ul class=\'ps-3 mb-2 small\'><li class=\'mb-1\'>Encapsulation: Bundling data and methods into classes.</li><li class=\'mb-1\'>Inheritance: Reusing code through class hierarchies.</li><li class=\'mb-1\'>Polymorphism: Method overloading and overriding.</li><li class=\'mb-1\'>Abstraction: Hiding implementation details using interfaces and abstract classes.</li></ul><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'CODING', '0.90', '2026-08-19 15:29:41');
