INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('517', '157', 'bot', '<p class=\'mb-2\'>We offer the following official degree programs and academic branches:</p><ol class=\'ps-3 mb-2 small\'><li class=\'mb-1\'>**B.Tech in Civil Engineering (BTECH-CIVIL)** — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'>**B.Tech in Computer Science & Engineering (BTECH-CSE)** — Duration: 4 Years (8 Semesters), Intake: 120 seats</li><li class=\'mb-1\'>**B.Tech in CSE (Artificial Intelligence & Machine Learning) (BTECH-AIML)** — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'>**B.Tech in CSE (Cyber Security & Digital Forensics) (BTECH-CS)** — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'>**B.Tech in Electronics & Communication Engineering (BTECH-ECE)** — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'>**B.Tech in Mechanical & Automation Engineering (BTECH-MECH)** — Duration: 4 Years (8 Semesters), Intake: 60 seats</li><li class=\'mb-1\'>**Integrated 6-Year B.Tech Program (After 10th Class) (INT-BTECH)** — Duration: 6 Years (12 Semesters), Intake: 60 seats</li><li class=\'mb-1\'>**M.Tech in Computer Science & Engineering (MTECH-CSE)** — Duration: 2 Years (4 Semesters), Intake: 30 seats</li></ol><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/courses.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'PROGRAM', '0.95', '2026-08-26 14:03:57');
