INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('587', '185', 'bot', '<p class=\'mb-2\'>Admissions to B.Tech programs at SOET are open for eligible candidates who have passed 10+2 (HSC) with Physics, Mathematics, and Chemistry/Biotechnology/Technical Vocational subjects securing at least 45% aggregate marks (40% for reserved categories). Valid scores in MHT-CET or JEE Main are preferred. Applications can be submitted online at http://localhost:8000/admissions.php.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/admissions.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'GENERAL_AI', '0.94', '2026-08-26 14:08:26');
