INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('681', '232', 'bot', '<p class=\'mb-2\'>Here are the official SOET college events, fests, and sub-events:</p><p class=\'mb-2\'>• **Supernova** (Date: 27-Aug-2026 at SOET Ground Floor)<br />\n  dhjckjc<br />\n  *Sub-Events / Tracks:*<br />\n   📌 **Code-A-Thon (36-Hour Hackathon)** (27-Aug at Central Computer Lab 3): Inter-college 36-hour continuous software development and problem solving competition.<br />\n   📌 **Robo Wars & Obstacle Race** (27-Aug at SOET Open Courtyard Arena): Wired and wireless bot combat and obstacle course navigation challenge.<br />\n   📌 **Paper & Poster Technical Presentation** (28-Aug at Auditorium Hall 1): Research paper presentation on AI, IoT, Cybersecurity, and Renewable Energy.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/events.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'EVENT', '0.95', '2026-08-26 14:39:59');
