INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('687', '235', 'bot', '<p class=\'mb-2\'>Here is the annual tuition fee breakdown for SOET degree programs:</p><p class=\'mb-2\'>• **B.Tech in Computer Science & Engineering (BTECH-CSE)**: ₹150,000 / year<br />\n• **B.Tech in Electronics & Communication Engineering (BTECH-ECE)**: ₹140,000 / year<br />\n• **B.Tech in CSE (Cyber Security & Digital Forensics) (BTECH-CS)**: ₹150,000 / year<br />\n• **M.Tech in Computer Science & Engineering (MTECH-CSE)**: ₹100,000 / year<br />\n• **B.Tech in CSE (Artificial Intelligence & Machine Learning) (BTECH-AIML)**: ₹150,000 / year<br />\n• **B.Tech in Mechanical & Automation Engineering (BTECH-MECH)**: ₹130,000 / year<br />\n• **B.Tech in Civil Engineering (BTECH-CIVIL)**: ₹130,000 / year<br />\n• **Integrated 6-Year B.Tech Program (After 10th Class) (INT-BTECH)**: ₹110,000 / year</p><p class=\'mb-2\'>Government SC/ST/OBC scholarships and MGM Merit Scholarships are available.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/courses.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'FEE', '0.95', '2026-08-26 14:39:59');
