INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('831', '294', 'bot', '<p class=\'mb-2\'>### Artificial Intelligence (AI)</p><p class=\'mb-2\'>Artificial Intelligence (AI) simulates human cognitive functions in software. Applications include Machine Learning, Neural Networks, Natural Language Processing (NLP), Computer Vision, and Robotics.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'GENERAL_AI', '0.90', '2026-08-29 13:59:54');
