INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('870', '308', 'user', 'What is binary search', 'system', 'USER_INPUT', '1.00', '2026-08-29 18:52:20');
INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('871', '308', 'bot', '<p class=\'mb-2\'>### Binary Search Algorithm</p><p class=\'mb-2\'>Binary Search is an efficient algorithm that searches a sorted array by repeatedly dividing the search interval in half. Time Complexity: O(log n).</p><p class=\'mb-2\'><div class=\'code-block-wrapper my-2\'><div class=\'code-block-header d-flex justify-content-between px-3 py-1 bg-dark text-white-50 rounded-top small font-monospace\'><span>c</span><button class=\'btn btn-link btn-sm text-white-50 p-0 copy-code-btn\' onclick=\'navigator.clipboard.writeText(this.parentNode.nextElementSibling.innerText)\'><i class=\'fa-regular fa-copy me-1\'></i>Copy</button></div><pre class=\'bg-dark text-light p-3 rounded-bottom mb-0 font-monospace\' style=\'max-height:300px; overflow-y:auto;\'><code>int binarySearch(int arr[], int size, int target) {<br />\n    int low = 0, high = size - 1;<br />\n    while (low &lt;= high) {<br />\n        int mid = low + (high - low) / 2;<br />\n        if (arr[mid] == target) return mid;<br />\n        if (arr[mid] &lt; target) low = mid + 1;<br />\n        else high = mid - 1;<br />\n    }<br />\n    return -1;<br />\n}</code></pre></div></p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'GENERAL_AI', '0.90', '2026-08-29 18:52:20');
