INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('901', '319', 'bot', '<p class=\'mb-2\'>### Java Programming</p><p class=\'mb-2\'>Java is a class-based, object-oriented language (\'Write Once, Run Anywhere\' via JVM).</p>OOP Pillars:\n<ol class=\'ps-3 mb-2 small\'><li class=\'mb-1\'>Encapsulation: Hiding internal data state.</li><li class=\'mb-1\'>Inheritance: Code reuse via parent-child classes.</li><li class=\'mb-1\'>Polymorphism: Method overloading and overriding.</li><li class=\'mb-1\'>Abstraction: Hiding implementation details via Interfaces and Abstract Classes.</li></ol><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'GENERAL_AI', '0.90', '2026-08-29 18:55:30');
