INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('915', '319', 'bot', '<p class=\'mb-2\'>Admission Procedure: 1. Online registration at MGM University portal (admissions.mgmu.ac.in). 2. Fill out application details and choose program preferences. 3. Appear for MGMU CET / submit valid MHT-CET or JEE Main scorecards. 4. Merit list generation and online counseling round. 5. Document verification and tuition fee payment at campus.</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 d-flex align-items-center justify-content-between text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-building-columns me-1\'></i>🤖 CampusAI — SOET Verified Data</span><a href=\'http://localhost:8000/admissions.php\' class=\'text-decoration-none text-primary font-semibold\' target=\'_blank\'>Explore Section <i class=\'fa-solid fa-arrow-up-right-from-square ms-1\'></i></a></div>', 'database', 'ADMISSION', '0.95', '2026-08-29 18:56:50');
