INSERT INTO `chat_messages` (`id`, `session_id`, `sender`, `message`, `source`, `intent`, `confidence`, `created_at`) VALUES ('917', '319', 'bot', '<p class=\'mb-2\'>🤖 **CampusAI — General Knowledge Overview**</p><p class=\'mb-2\'>### Ground</p><p class=\'mb-2\'>Here is a helpful overview regarding **Ground**:</p><p class=\'mb-2\'>• **Definition & Core Concept**: Ground is a key concept studied across engineering, science, and technological disciplines.<br />\n• **Applications & Importance**: It plays a vital role in practical applications, domain research, and problem-solving methodologies.</p><p class=\'mb-2\'>💡 *You can also ask CampusAI about SOET engineering programs, fee structures, faculty details, or live seat availability!*</p><div class=\'source-badge mt-2 pt-2 border-top border-secondary border-opacity-10 text-muted small\' style=\'font-size:11px;\'>\n                        <span class=\'badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 rounded-pill px-2 py-1\'><i class=\'fa-solid fa-brain me-1\'></i>🤖 CampusAI — AI Knowledge</span>\n                      </div>', 'openai', 'GENERAL_AI', '0.90', '2026-08-29 18:57:56');
