INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('1', 'What is the eligibility for B.Tech admission at SOET?', 'Candidates must have passed 10+2 with Physics and Mathematics as compulsory subjects with 45% aggregate marks (40% for SC/ST/OBC). MHT-CET or JEE Main score card is required.', 'admissions', 'eligibility, 12th, percentage, cut off, criteria', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('2', 'What is the highest salary package offered at SOET placements?', 'The highest salary package offered is RS 18.5 LPA by a global software multinational, with an average package of RS 5.2 LPA across all branches.', 'placements', 'highest package, highest salary, CTC, package', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('3', 'Is hostel facility available on campus?', 'Yes, SOET provides separate modern residential hostels for boys and girls with 24/7 security, Wi-Fi, gym, hygienic mess, and medical care.', 'general', 'hostel, residence, room, stay, accommodation, mess', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('4', 'Are scholarships available for students?', 'Yes, government scholarships for SC/ST/OBC/EBC candidates as well as MGM Merit Scholarships are available for top-ranking CET/JEE students.', 'admissions', 'scholarship, fee concession, freeship, financial assistance', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
INSERT INTO `faq` (`id`, `question`, `answer`, `category`, `keywords`, `status`, `created_at`, `updated_at`) VALUES ('5', 'How can I contact the CSE Department HOD?', 'You can contact the CSE HOD via email at cse.hod@soet.edu or visit the CSE Department office in Academic Block 2, 1st Floor.', 'faculty', 'cse hod, head cse, contact hod, email cse', 'active', '2026-08-11 15:22:44', '2026-08-11 15:22:44');
